1529	    private void doEscPound(int b) {
1530	        switch (b) {
1531	            case '8': // Esc # 8 - DEC screen alignment test - fill screen with E's.
1532	                mScreen.blockSet(0, 0, mColumns, mRows, 'E', getStyle());
1533	                break;
1534	            default:
1535	                unknownSequence(b);
1536	                break;
1537	        }
