1540	    /** Encountering a character in the {@link #ESC} state. */
1541	    private void doEsc(int b) {
1542	        switch (b) {
1543	            case '#':
1544	                continueSequence(ESC_POUND);
1545	                break;
1546	            case '(':
1547	                continueSequence(ESC_SELECT_LEFT_PAREN);
1548	                break;
1549	            case ')':
1550	                continueSequence(ESC_SELECT_RIGHT_PAREN);
1551	                break;
1552	            case '6': // Back index (http://www.vt100.net/docs/vt510-rm/DECBI). Move left, insert blank column if start.
1553	                doEscBackIndex();
1554	                break;
1555	            case '7': // DECSC save cursor - http://www.vt100.net/docs/vt510-rm/DECSC
1556	                saveCursor();
1557	                break;
1558	            case '8': // DECRC restore cursor - http://www.vt100.net/docs/vt510-rm/DECRC
1559	                restoreCursor();
1560	                break;
1561	            case '9': // Forward Index (http://www.vt100.net/docs/vt510-rm/DECFI). Move right, insert blank column if end.
1562	                doEscForwardIndex();
1563	                break;
1564	            case 'c': // RIS - Reset to Initial State (http://vt100.net/docs/vt510-rm/RIS).
1565	                doEscFullReset();
1566	                break;
1567	            case 'D': // INDEX
1568	                doLinefeed();
1569	                break;
1570	            case 'E': // Next line (http://www.vt100.net/docs/vt510-rm/NEL).
1571	                setCursorCol(isDecsetInternalBitSet(DECSET_BIT_ORIGIN_MODE) ? mLeftMargin : 0);
1572	                doLinefeed();
1573	                break;
1574	            case 'F': // Cursor to lower-left corner of screen
1575	                setCursorRowColAbsolute(0, mBottomMargin - 1);
1576	                break;
1577	            case 'H': // Tab set
1578	                mTabStop[mCursorCol] = true;
1579	                break;
1580	            case 'M': // "${ESC}M" - reverse index (RI).
1581	                doEscReverseIndex();
1582	                break;
1583	            case 'N': // SS2, ignore.
1584	            case '0': // SS3, ignore.
1585	                break;
1586	            case 'P': // Device control string
1587	                mOSCOrDeviceControlArgs.setLength(0);
1588	                continueSequence(ESC_P);
1589	                break;
1590	            case '[':
1591	                continueSequence(ESC_CSI);
1592	                break;
1593	            case '=': // DECKPAM
1594	                setDecsetinternalBit(DECSET_BIT_APPLICATION_KEYPAD, true);
1595	                break;
1596	            case ']': // OSC
1597	                mOSCOrDeviceControlArgs.setLength(0);
1598	                continueSequence(ESC_OSC);
1599	                break;
1600	            case '>': // DECKPNM
1601	                setDecsetinternalBit(DECSET_BIT_APPLICATION_KEYPAD, false);
1602	                break;
1603	            case '_': // APC - Application Program Command.
1604	                continueSequence(ESC_APC);
1605	                break;
1606	            default:
1607	                unknownSequence(b);
1608	                break;
1609	        }
1610	    }
