1612	    /** DECSC save cursor - http://www.vt100.net/docs/vt510-rm/DECSC . See {@link #restoreCursor()}. */
1613	    private void saveCursor() {
1614	        SavedScreenState state = (mScreen == mMainBuffer) ? mSavedStateMain : mSavedStateAlt;
1615	        state.mSavedCursorRow = mCursorRow;
1616	        state.mSavedCursorCol = mCursorCol;
1617	        state.mSavedEffect = mEffect;
1618	        state.mSavedForeColor = mForeColor;
1619	        state.mSavedBackColor = mBackColor;
1620	        state.mSavedDecFlags = mCurrentDecSetFlags;
1621	        state.mUseLineDrawingG0 = mUseLineDrawingG0;
1622	        state.mUseLineDrawingG1 = mUseLineDrawingG1;
1623	        state.mUseLineDrawingUsesG0 = mUseLineDrawingUsesG0;
1624	    }
