1626	    /** DECRS restore cursor - http://www.vt100.net/docs/vt510-rm/DECRC. See {@link #saveCursor()}. */
1627	    private void restoreCursor() {
1628	        SavedScreenState state = (mScreen == mMainBuffer) ? mSavedStateMain : mSavedStateAlt;
1629	        setCursorRowColAbsolute(state.mSavedCursorRow, state.mSavedCursorCol);
1630	        mEffect = state.mSavedEffect;
1631	        mForeColor = state.mSavedForeColor;
1632	        mBackColor = state.mSavedBackColor;
1633	        int mask = (DECSET_BIT_AUTOWRAP | DECSET_BIT_ORIGIN_MODE);
1634	        mCurrentDecSetFlags = (mCurrentDecSetFlags & ~mask) | (state.mSavedDecFlags & mask);
1635	        mUseLineDrawingG0 = state.mUseLineDrawingG0;
1636	        mUseLineDrawingG1 = state.mUseLineDrawingG1;
1637	        mUseLineDrawingUsesG0 = state.mUseLineDrawingUsesG0;
1638	    }
