1640	    /** Following a CSI - Control Sequence Introducer, "\033[". {@link #ESC_CSI}. */
1641	    private void doCsi(int b) {
1642	        switch (b) {
1643	            case '!':
1644	                continueSequence(ESC_CSI_EXCLAMATION);
1645	                break;
1646	            case '"':
1647	                continueSequence(ESC_CSI_DOUBLE_QUOTE);
1648	                break;
1649	            case '\'':
1650	                continueSequence(ESC_CSI_SINGLE_QUOTE);
1651	                break;
1652	            case '$':
1653	                continueSequence(ESC_CSI_DOLLAR);
1654	                break;
1655	            case '*':
1656	                continueSequence(ESC_CSI_ARGS_ASTERIX);
1657	                break;
1658	            case '@': // "CSI{n}@" - Insert ${n} space characters (ICH) - http://www.vt100.net/docs/vt510-rm/ICH.
1659	                doCsiInsertChars();
1660	                break;
1661	            case 'A': // "CSI${n}A" - Cursor up (CUU) ${n} rows.
1662	                setCursorRow(Math.max(0, mCursorRow - getArg0(1)));
1663	                break;
1664	            case 'B': // "CSI${n}B" - Cursor down (CUD) ${n} rows.
1665	                setCursorRow(Math.min(mRows - 1, mCursorRow + getArg0(1)));
1666	                break;
1667	            case 'C': // "CSI${n}C" - Cursor forward (CUF).
1668	            case 'a': // "CSI${n}a" - Horizontal position relative (HPR). From ISO-6428/ECMA-48.
1669	                setCursorCol(Math.min(mRightMargin - 1, mCursorCol + getArg0(1)));
1670	                break;
1671	            case 'D': // "CSI${n}D" - Cursor backward (CUB) ${n} columns.
1672	                setCursorCol(Math.max(mLeftMargin, mCursorCol - getArg0(1)));
1673	                break;
1674	            case 'E': // "CSI{n}E - Cursor Next Line (CNL). From ISO-6428/ECMA-48.
1675	                setCursorPosition(0, mCursorRow + getArg0(1));
1676	                break;
1677	            case 'F': // "CSI{n}F - Cursor Previous Line (CPL). From ISO-6428/ECMA-48.
1678	                setCursorPosition(0, mCursorRow - getArg0(1));
1679	                break;
1680	            case 'G': // "CSI${n}G" - Cursor horizontal absolute (CHA) to column ${n}.
1681	                setCursorCol(Math.min(Math.max(1, getArg0(1)), mColumns) - 1);
1682	                break;
1683	            case 'H': // "${CSI}${ROW};${COLUMN}H" - Cursor position (CUP).
1684	            case 'f': // "${CSI}${ROW};${COLUMN}f" - Horizontal and Vertical Position (HVP).
1685	                setCursorPosition(getArg1(1) - 1, getArg0(1) - 1);
1686	                break;
1687	            case 'I': // Cursor Horizontal Forward Tabulation (CHT). Move the active position n tabs forward.
1688	                setCursorCol(nextTabStop(getArg0(1)));
1689	                break;
1690	            case 'J': // "${CSI}${0,1,2,3}J" - Erase in Display (ED)
1691	                doCsiEraseInDisplay(b);
1692	                break;
1693	            case 'K': // "CSI{n}K" - Erase in line (EL).
1694	                doCsiEraseInLine(b);
1695	                break;
1696	            case 'L': // "${CSI}{N}L" - insert ${N} lines (IL).
1697	                doCsiInsertLines();
1698	                break;
1699	            case 'M': // "${CSI}${N}M" - delete N lines (DL).
1700	                doCsiDeleteLines();
1701	                break;
1702	            case 'P': // "${CSI}{N}P" - delete ${N} characters (DCH).
1703	                doCsiDeleteChars();
1704	                break;
1705	            case 'S': // "${CSI}${N}S" - scroll up ${N} lines (default = 1) (SU).
1706	                doCsiScrollUp();
1707	                break;
1708	            case 'T':
1709	                doCsiScrollDownOrHighlightTracking(b);
1710	                break;
1711	            case 'X': // "${CSI}${N}X" - Erase ${N:=1} character(s) (ECH). FIXME: Clears character attributes?
1712	                mAboutToAutoWrap = false;
1713	                mScreen.blockSet(mCursorCol, mCursorRow, Math.min(getArg0(1), mColumns - mCursorCol), 1, ' ', getStyle());
1714	                break;
1715	            case 'Z': // Cursor Backward Tabulation (CBT). Move the active position n tabs backward.
1716	                doCsiCursorBackwardTabulation();
1717	                break;
1718	            case '?': // Esc [ ? -- start of a private parameter byte
1719	                continueSequence(ESC_CSI_QUESTIONMARK);
1720	                break;
1721	            case '>': // "Esc [ >" -- start of a private parameter byte
1722	                continueSequence(ESC_CSI_BIGGERTHAN);
1723	                break;
1724	            case '<': // "Esc [ <" -- start of a private parameter byte
1725	            case '=': // "Esc [ =" -- start of a private parameter byte
1726	                continueSequence(ESC_CSI_UNSUPPORTED_PARAMETER_BYTE);
1727	                break;
1728	            case '`': // Horizontal position absolute (HPA - http://www.vt100.net/docs/vt510-rm/HPA).
1729	                setCursorColRespectingOriginMode(getArg0(1) - 1);
1730	                break;
1731	            case 'b': // Repeat the preceding graphic character Ps times (REP).
1732	                doCsiRepeat();
1733	                break;
1734	            case 'c': // Primary Device Attributes (http://www.vt100.net/docs/vt510-rm/DA1) if argument is missing or zero.
1735	                // The important part that may still be used by some (tmux stores this value but does not currently use it)
1736	                // is the first response parameter identifying the terminal service class, where we send 64 for "vt420".
1737	                // This is followed by a list of attributes which is probably unused by applications. Send like xterm.
1738	                if (getArg0(0) == 0) mSession.write("\033[?64;1;2;6;9;15;18;21;22c");
1739	                break;
1740	            case 'd': // ESC [ Pn d - Vert Position Absolute
1741	                setCursorRow(Math.min(Math.max(1, getArg0(1)), mRows) - 1);
1742	                break;
1743	            case 'e': // Vertical Position Relative (VPR). From ISO-6429 (ECMA-48).
1744	                setCursorPosition(mCursorCol, mCursorRow + getArg0(1));
1745	                break;
1746	            // case 'f': "${CSI}${ROW};${COLUMN}f" - Horizontal and Vertical Position (HVP). Grouped with case 'H'.
1747	            case 'g': // Clear tab stop
1748	                doCsiClearTabStop();
1749	                break;
1750	            case 'h': // Set Mode
1751	                doSetMode(true);
1752	                break;
1753	            case 'l': // Reset Mode
1754	                doSetMode(false);
1755	                break;
1756	            case 'm': // Esc [ Pn m - character attributes. (can have up to 16 numerical arguments)
1757	                selectGraphicRendition();
1758	                break;
1759	            case 'n': // Esc [ Pn n - ECMA-48 Status Report Commands
1760	                doCsiDeviceStatusReport();
1761	                break;
1762	            case 'r': // "CSI${top};${bottom}r" - set top and bottom Margins (DECSTBM).
1763	                doCsiSetScrollMargins();
1764	                break;
1765	            case 's': // DECSLRM or ANSI.SYS save cursor.
1766	                doCsiDecslrmOrSaveCursor();
1767	                break;
1768	            case 't': // Window manipulation (from dtterm, as well as extensions)
1769	                doCsiWindowManipulation();
1770	                break;
1771	            case 'u': // Restore cursor (ANSI.SYS).
1772	                restoreCursor();
1773	                break;
1774	            case ' ':
1775	                continueSequence(ESC_CSI_ARGS_SPACE);
1776	                break;
1777	            default:
1778	                parseArg(b);
1779	                break;
1780	        }
1781	    }
