1791	    /** REP — repeat the preceding graphic character N times. */
1792	    private void doCsiRepeat() {
1793	        if (mLastEmittedCodePoint == -1) return;
1794	        int numRepeat = getArg0(1);
1795	        for (int i = 0; i < numRepeat; i++) emitCodePoint(mLastEmittedCodePoint);
1796	    }
