1798	    /** ICH — insert N space characters at cursor, shifting existing chars right. */
1799	    private void doCsiInsertChars() {
1800	        mAboutToAutoWrap = false;
1801	        int columnsAfterCursor = mColumns - mCursorCol;
1802	        int spacesToInsert = Math.min(getArg0(1), columnsAfterCursor);
1803	        int charsToMove = columnsAfterCursor - spacesToInsert;
1804	        mScreen.blockCopy(mCursorCol, mCursorRow, charsToMove, 1, mCursorCol + spacesToInsert, mCursorRow);
1805	        blockClear(mCursorCol, mCursorRow, spacesToInsert);
1806	    }
1807	
1808	    /** IL — insert N blank lines at cursor row, scrolling lines below down. */
1809	    private void doCsiInsertLines() {
1810	        int linesAfterCursor = mBottomMargin - mCursorRow;
1811	        int linesToInsert = Math.min(getArg0(1), linesAfterCursor);
1812	        int linesToMove = linesAfterCursor - linesToInsert;
1813	        mScreen.blockCopy(0, mCursorRow, mColumns, linesToMove, 0, mCursorRow + linesToInsert);
1814	        blockClear(0, mCursorRow, mColumns, linesToInsert);
1815	    }
1816	
1817	    /** DL — delete N lines at cursor row, scrolling lines below up. */
1818	    private void doCsiDeleteLines() {
1819	        mAboutToAutoWrap = false;
1820	        int linesAfterCursor = mBottomMargin - mCursorRow;
1821	        int linesToDelete = Math.min(getArg0(1), linesAfterCursor);
1822	        int linesToMove = linesAfterCursor - linesToDelete;
1823	        mScreen.blockCopy(0, mCursorRow + linesToDelete, mColumns, linesToMove, 0, mCursorRow);
1824	        blockClear(0, mCursorRow + linesToMove, mColumns, linesToDelete);
1825	    }
