1827	    /** DCH — delete N characters at cursor, shifting remaining chars on the line left. */
1828	    private void doCsiDeleteChars() {
1829	        // http://www.vt100.net/docs/vt510-rm/DCH: "If ${N} is greater than the number of characters between the
1830	        // cursor and the right margin, then DCH only deletes the remaining characters.
1831	        // As characters are deleted, the remaining characters between the cursor and right margin move to the left.
1832	        // Character attributes move with the characters. The terminal adds blank spaces with no visual character
1833	        // attributes at the right margin. DCH has no effect outside the scrolling margins."
1834	        mAboutToAutoWrap = false;
1835	        int cellsAfterCursor = mColumns - mCursorCol;
1836	        int cellsToDelete = Math.min(getArg0(1), cellsAfterCursor);
1837	        int cellsToMove = cellsAfterCursor - cellsToDelete;
1838	        mScreen.blockCopy(mCursorCol + cellsToDelete, mCursorRow, cellsToMove, 1, mCursorCol, mCursorRow);
1839	        blockClear(mCursorCol + cellsToMove, mCursorRow, cellsToDelete);
1840	    }
