1842	    /**
1843	     * DECSTBM — Set top and bottom scroll margins (https://vt100.net/docs/vt510-rm/DECSTBM.html).
1844	     * Top defaults to 1, bottom defaults to mRows. Escape numbers top 1..N-1 (we subtract 1).
1845	     * Bottom is stored as the first line BELOW the bottom margin, so we leave it as-is.
1846	     * Also requires top + 2 <= bottom.
1847	     */
1848	    private void doCsiSetScrollMargins() {
1849	        mTopMargin = Math.max(0, Math.min(getArg0(1) - 1, mRows - 2));
1850	        mBottomMargin = Math.max(mTopMargin + 2, Math.min(getArg1(mRows), mRows));
1851	        // DECSTBM moves the cursor to column 1, line 1 of the page respecting origin mode.
1852	        setCursorPosition(0, 0);
1853	    }
