1855	    /** DECSLRM (when DECLRMM is set) or ANSI.SYS save cursor (otherwise). */
1856	    private void doCsiDecslrmOrSaveCursor() {
1857	        if (isDecsetInternalBitSet(DECSET_BIT_LEFTRIGHT_MARGIN_MODE)) {
1858	            // Set left and right margins (DECSLRM - http://www.vt100.net/docs/vt510-rm/DECSLRM).
1859	            mLeftMargin = Math.min(getArg0(1) - 1, mColumns - 2);
1860	            mRightMargin = Math.max(mLeftMargin + 1, Math.min(getArg1(mColumns), mColumns));
1861	            // DECSLRM moves the cursor to column 1, line 1 of the page.
1862	            setCursorPosition(0, 0);
1863	        } else {
1864	            // Save cursor (ANSI.SYS), available only when DECLRMM is disabled.
1865	            saveCursor();
1866	        }
1867	    }
