1869	    private void doCsiEraseInDisplay(int b) {
1870	        // ED ignores the scrolling margins.
1871	        switch (getArg0(0)) {
1872	            case 0: // Erase from the active position to the end of the screen, inclusive (default).
1873	                blockClear(mCursorCol, mCursorRow, mColumns - mCursorCol);
1874	                blockClear(0, mCursorRow + 1, mColumns, mRows - (mCursorRow + 1));
1875	                break;
1876	            case 1: // Erase from start of the screen to the active position, inclusive.
1877	                blockClear(0, 0, mColumns, mCursorRow);
1878	                blockClear(0, mCursorRow, mCursorCol + 1);
1879	                break;
1880	            case 2: // Erase all of the display - all lines are erased, changed to single-width, and the cursor does not
1881	                // move..
1882	                blockClear(0, 0, mColumns, mRows);
1883	                break;
1884	            case 3: // Delete all lines saved in the scrollback buffer (xterm etc)
1885	                mMainBuffer.clearTranscript();
1886	                break;
1887	            default:
1888	                unknownSequence(b);
1889	                return;
1890	        }
1891	        mAboutToAutoWrap = false;
1892	    }
