1894	    /** EL — erase in line (K). Note: default: case uses return to skip mAboutToAutoWrap=false. */
1895	    private void doCsiEraseInLine(int b) {
1896	        switch (getArg0(0)) {
1897	            case 0: // Erase from the cursor to the end of the line, inclusive (default)
1898	                blockClear(mCursorCol, mCursorRow, mColumns - mCursorCol);
1899	                break;
1900	            case 1: // Erase from the start of the screen to the cursor, inclusive.
1901	                blockClear(0, mCursorRow, mCursorCol + 1);
1902	                break;
1903	            case 2: // Erase all of the line.
1904	                blockClear(0, mCursorRow, mColumns);
1905	                break;
1906	            default:
1907	                unknownSequence(b);
1908	                return;
1909	        }
1910	        mAboutToAutoWrap = false;
1911	    }
