1913	    /** SD / highlight mouse tracking (T). */
1914	    private void doCsiScrollDownOrHighlightTracking(int b) {
1915	        if (mArgIndex == 0) {
1916	            // "${CSI}${N}T" - Scroll down N lines (default = 1) (SD).
1917	            // http://vt100.net/docs/vt510-rm/SD: "N is the number of lines to move the user window up in page
1918	            // memory. N new lines appear at the top of the display. N old lines disappear at the bottom of the
1919	            // display. You cannot pan past the top margin of the current page".
1920	            final int linesToScrollArg = getArg0(1);
1921	            final int linesBetweenTopAndBottomMargins = mBottomMargin - mTopMargin;
1922	            final int linesToScroll = Math.min(linesBetweenTopAndBottomMargins, linesToScrollArg);
1923	            mScreen.blockCopy(mLeftMargin, mTopMargin, mRightMargin - mLeftMargin, linesBetweenTopAndBottomMargins - linesToScroll, mLeftMargin, mTopMargin + linesToScroll);
1924	            blockClear(mLeftMargin, mTopMargin, mRightMargin - mLeftMargin, linesToScroll);
1925	        } else {
1926	            // "${CSI}${func};${startx};${starty};${firstrow};${lastrow}T" - initiate highlight mouse tracking.
1927	            unimplementedSequence(b);
1928	        }
1929	    }
