1931	    /** CBT — cursor backward tabulation (Z). */
1932	    private void doCsiCursorBackwardTabulation() {
1933	        int numberOfTabs = getArg0(1);
1934	        int newCol = mLeftMargin;
1935	        for (int i = mCursorCol - 1; i >= 0; i--)
1936	            if (mTabStop[i]) {
1937	                if (--numberOfTabs == 0) {
1938	                    newCol = Math.max(i, mLeftMargin);
1939	                    break;
1940	                }
1941	            }
1942	        mCursorCol = newCol;
1943	    }
