1945	    /** TBC — clear tab stop (g). */
1946	    private void doCsiClearTabStop() {
1947	        switch (getArg0(0)) {
1948	            case 0:
1949	                mTabStop[mCursorCol] = false;
1950	                break;
1951	            case 3:
1952	                Arrays.fill(mTabStop, false);
1953	                break;
1954	            default:
1955	                // Specified to have no effect.
1956	                break;
1957	        }
1958	    }
