1960	    /** DSR/CPR — device status report and cursor position report (n). */
1961	    private void doCsiDeviceStatusReport() {
1962	        switch (getArg0(0)) {
1963	            case 5: // Device status report (DSR):
1964	                // Answer is ESC [ 0 n (Terminal OK).
1965	                byte[] dsr = {(byte) 27, (byte) '[', (byte) '0', (byte) 'n'};
1966	                mSession.write(dsr, 0, dsr.length);
1967	                break;
1968	            case 6: // Cursor position report (CPR):
1969	                // Answer is ESC [ y ; x R, where x,y is
1970	                // the cursor location.
1971	                mSession.write(String.format(Locale.US, "\033[%d;%dR", mCursorRow + 1, mCursorCol + 1));
1972	                break;
1973	            default:
1974	                break;
1975	        }
1976	    }
