1978	    /** XTWINOPS — window manipulation (t). */
1979	    private void doCsiWindowManipulation() {
1980	        switch (getArg0(0)) {
1981	            case 11: // Report xterm window state. If the xterm window is open (non-iconified), it returns CSI 1 t .
1982	                mSession.write("\033[1t");
1983	                break;
1984	            case 13: // Report xterm window position. Result is CSI 3 ; x ; y t
1985	                mSession.write("\033[3;0;0t");
1986	                break;
1987	            case 14: // Report xterm window in pixels. Result is CSI 4 ; height ; width t
1988	                mSession.write(String.format(Locale.US, "\033[4;%d;%dt", mRows * mCellHeightPixels, mColumns * mCellWidthPixels));
1989	                break;
1990	            case 16: // Report xterm character cell size in pixels. Result is CSI 6 ; height ; width t
1991	                mSession.write(String.format(Locale.US, "\033[6;%d;%dt", mCellHeightPixels, mCellWidthPixels));
1992	                break;
1993	            case 18: // Report the size of the text area in characters. Result is CSI 8 ; height ; width t
1994	                mSession.write(String.format(Locale.US, "\033[8;%d;%dt", mRows, mColumns));
1995	                break;
1996	            case 19: // Report the size of the screen in characters. Result is CSI 9 ; height ; width t
1997	                // We report the same size as the view, since it's the view really isn't resizable from the shell.
1998	                mSession.write(String.format(Locale.US, "\033[9;%d;%dt", mRows, mColumns));
1999	                break;
2000	            case 20: // Report xterm windows icon label. Result is OSC L label ST. Disabled due to security concerns:
2001	                mSession.write("\033]LIconLabel\033\\");
2002	                break;
2003	            case 21: // Report xterm windows title. Result is OSC l label ST. Disabled due to security concerns:
2004	                mSession.write("\033]l\033\\");
2005	                break;
2006	            case 22:
2007	                // 22;0 -> Save xterm icon and window title on stack.
2008	                // 22;1 -> Save xterm icon title on stack.
2009	                // 22;2 -> Save xterm window title on stack.
2010	                mTitleStack.push(mTitle);
2011	                if (mTitleStack.size() > 20) {
2012	                    // Limit size
2013	                    mTitleStack.remove(0);
2014	                }
2015	                break;
2016	            case 23: // Like 22 above but restore from stack.
2017	                if (!mTitleStack.isEmpty()) setTitle(mTitleStack.pop());
2018	                break;
2019	            default:
2020	                // Ignore window manipulation.
2021	                break;
