2025	    /** Select Graphic Rendition (SGR) - see http://en.wikipedia.org/wiki/ANSI_escape_code#graphics. */
2026	    private void selectGraphicRendition() {
2027	        clampArgIndex();
2028	        for (int i = 0; i <= mArgIndex; i++) {
2029	            // Skip leading sub parameters:
2030	            if ((mArgsSubParamsBitSet & (1 << i)) != 0) {
2031	                continue;
2032	            }
2033	
2034	            int code = getArg(i, 0, false);
2035	            if (code < 0) {
2036	                if (mArgIndex > 0) {
2037	                    continue;
2038	                } else {
2039	                    code = 0;
2040	                }
2041	            }
2042	            if (code == 0) { // reset
2043	                mForeColor = TextStyle.COLOR_INDEX_FOREGROUND;
2044	                mBackColor = TextStyle.COLOR_INDEX_BACKGROUND;
2045	                mEffect = 0;
2046	            } else if (code == 1) {
2047	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_BOLD;
2048	            } else if (code == 2) {
2049	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_DIM;
2050	            } else if (code == 3) {
2051	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_ITALIC;
2052	            } else if (code == 4) {
2053	                if (i + 1 <= mArgIndex && ((mArgsSubParamsBitSet & (1 << (i + 1))) != 0)) {
2054	                    i = applySgrUnderlineSubParam(i);
2055	                } else {
2056	                    mEffect |= TextStyle.CHARACTER_ATTRIBUTE_UNDERLINE;
2057	                }
2058	            } else if (code == 5) {
2059	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_BLINK;
2060	            } else if (code == 7) {
2061	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_INVERSE;
2062	            } else if (code == 8) {
2063	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_INVISIBLE;
2064	            } else if (code == 9) {
2065	                mEffect |= TextStyle.CHARACTER_ATTRIBUTE_STRIKETHROUGH;
2066	            } else if (code == 10) {
2067	                // Exit alt charset (TERM=linux) - ignore.
2068	            } else if (code == 11) {
2069	                // Enter alt charset (TERM=linux) - ignore.
2070	            } else if (code == 22) { // Normal color or intensity, neither bright, bold nor faint.
2071	                mEffect &= ~(TextStyle.CHARACTER_ATTRIBUTE_BOLD | TextStyle.CHARACTER_ATTRIBUTE_DIM);
2072	            } else if (code == 23) { // not italic, but rarely used as such; clears standout with TERM=screen
2073	                mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_ITALIC;
2074	            } else if (code == 24) { // underline: none
2075	                mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_UNDERLINE;
2076	            } else if (code == 25) { // blink: none
2077	                mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_BLINK;
2078	            } else if (code == 27) { // image: positive
2079	                mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_INVERSE;
2080	            } else if (code == 28) {
2081	                mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_INVISIBLE;
2082	            } else if (code == 29) {
2083	                mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_STRIKETHROUGH;
2084	            } else if (code >= 30 && code <= 37) {
2085	                mForeColor = code - 30;
2086	            } else if (code == 38 || code == 48 || code == 58) {
2087	                // Extended set foreground(38)/background(48)/underline(58) color.
2088	                i = applyExtendedColorSgr(code, i);
2089	            } else if (code == 39) { // Set default foreground color.
2090	                mForeColor = TextStyle.COLOR_INDEX_FOREGROUND;
2091	            } else if (code >= 40 && code <= 47) { // Set background color.
2092	                mBackColor = code - 40;
2093	            } else if (code == 49) { // Set default background color.
2094	                mBackColor = TextStyle.COLOR_INDEX_BACKGROUND;
2095	            } else if (code == 59) { // Set default underline color.
2096	                mUnderlineColor = TextStyle.COLOR_INDEX_FOREGROUND;
2097	            } else if (code >= 90 && code <= 97) { // Bright foreground colors (aixterm codes).
2098	                mForeColor = code - 90 + 8;
2099	            } else if (code >= 100 && code <= 107) { // Bright background color (aixterm codes).
2100	                mBackColor = code - 100 + 8;
2101	            } else {
2102	                if (LOG_ESCAPE_SEQUENCES)
2103	                    Logger.logWarn(mClient, LOG_TAG, String.format("SGR unknown code %d", code));
2104	            }
2105	        }
2106	    }
