2108	    /**
2109	     * Handles SGR extended color introduction (codes 38=fg, 48=bg, 58=underline). Returns the new loop
2110	     * index after consuming sub-parameters ("2;r;g;b" → +4, "5;idx" → +2). The "continue" case (too few
2111	     * args) returns i unchanged; the outer for-loop's i++ advances past the introducer code.
2112	     */
2113	    private int applyExtendedColorSgr(int code, int i) {
2114	        // This is followed by either "2;$R;$G;$B" to set a 24-bit color or "5;$INDEX" to set an indexed color.
2115	        if (i + 2 > mArgIndex) return i;
2116	        int firstArg = mArgs[i + 1];
2117	        if (firstArg == 2) {
2118	            if (i + 4 > mArgIndex) {
2119	                Logger.logWarn(mClient, LOG_TAG, "Too few CSI" + code + ";2 RGB arguments");
2120	            } else {
2121	                int red = getArg(i + 2, 0, false);
2122	                int green = getArg(i + 3, 0, false);
2123	                int blue = getArg(i + 4, 0, false);
2124	                if (red < 0 || green < 0 || blue < 0 || red > 255 || green > 255 || blue > 255) {
2125	                    finishSequenceAndLogError("Invalid RGB: " + red + "," + green + "," + blue);
2126	                } else {
2127	                    setSgrColor(code, 0xff_00_00_00 | (red << 16) | (green << 8) | blue);
2128	                }
2129	                i += 4; // "2;P_r;P_g;P_b"
2130	            }
2131	        } else if (firstArg == 5) {
2132	            int color = getArg(i + 2, 0, false);
2133	            i += 2; // "5;P_s"
2134	            if (color >= 0 && color < TextStyle.NUM_INDEXED_COLORS) {
2135	                setSgrColor(code, color);
2136	            } else {
2137	                if (LOG_ESCAPE_SEQUENCES) Logger.logWarn(mClient, LOG_TAG, "Invalid color index: " + color);
2138	            }
2139	        } else {
2140	            finishSequenceAndLogError("Invalid ISO-8613-3 SGR first argument: " + firstArg);
2141	        }
2142	        return i;
2143	    }
