2145	    /** Handles SGR 4 kitty underline sub-parameter: advances past it, sets or clears underline. Returns new index. */
2146	    private int applySgrUnderlineSubParam(int i) {
2147	        // Sub parameter, see https://sw.kovidgoyal.net/kitty/underlines/
2148	        i++;
2149	        if (mArgs[i] == 0) {
2150	            // No underline.
2151	            mEffect &= ~TextStyle.CHARACTER_ATTRIBUTE_UNDERLINE;
2152	        } else {
2153	            // Different variations of underlines: https://sw.kovidgoyal.net/kitty/underlines/
2154	            mEffect |= TextStyle.CHARACTER_ATTRIBUTE_UNDERLINE;
2155	        }
2156	        return i;
2157	    }
