2197	    /** An Operating System Controls (OSC) Set Text Parameters. May come here from BEL or ST. */
2198	    private void doOscSetTextParameters(String bellOrStringTerminator) {
2199	        int value = -1;
2200	        String textParameter = "";
2201	        // Extract initial $value from initial "$value;..." string.
2202	        for (int mOSCArgTokenizerIndex = 0; mOSCArgTokenizerIndex < mOSCOrDeviceControlArgs.length(); mOSCArgTokenizerIndex++) {
2203	            char b = mOSCOrDeviceControlArgs.charAt(mOSCArgTokenizerIndex);
2204	            if (b == ';') {
2205	                textParameter = mOSCOrDeviceControlArgs.substring(mOSCArgTokenizerIndex + 1);
2206	                break;
2207	            } else if (b >= '0' && b <= '9') {
2208	                value = ((value < 0) ? 0 : value * 10) + (b - '0');
2209	            } else {
2210	                unknownSequence(b);
2211	                return;
2212	            }
2213	        }
2214	
2215	        switch (value) {
2216	            case 0: // Change icon name and window title to T.
2217	            case 1: // Change icon name to T.
2218	            case 2: // Change window title to T.
2219	                setTitle(textParameter);
2220	                break;
2221	            case 4:
2222	                if (!oscChangeColors(textParameter)) return;
2223	                break;
2224	            case 10: // Set foreground color.
2225	            case 11: // Set background color.
2226	            case 12: // Set cursor color.
2227	                oscSetOrReportSpecialColors(value, textParameter, bellOrStringTerminator);
2228	                break;
2229	            case 52: // Manipulate Selection Data. Skip the optional first selection parameter(s).
2230	                oscManipulateSelection(textParameter);
2231	                break;
2232	            case 104:
2233	                oscResetColors(textParameter);
2234	                break;
2235	            case 110: // Reset foreground color.
2236	            case 111: // Reset background color.
2237	            case 112: // Reset cursor color.
2238	                mColors.reset(TextStyle.COLOR_INDEX_FOREGROUND + (value - 110));
2239	                mSession.onColorsChanged();
2240	                break;
2241	            case 119: // Reset highlight color.
2242	                break;
2243	            default:
2244	                unknownParameter(value);
2245	                break;
2246	        }
2247	        finishSequence();
2248	    }
