2261	    /**
2262	     * OSC 4 — change indexed color. Returns false (and calls unknownSequence) if the color index is invalid, so
2263	     * the caller can return early to skip finishSequence().
2264	     */
2265	    private boolean oscChangeColors(String text) {
2266	        // P s = 4 ; c ; spec → Change Color Number c to the color specified by spec. This can be a name or RGB
2267	        // specification as per XParseColor. Any number of c name pairs may be given. The color numbers correspond
2268	        // to the ANSI colors 0-7, their bright versions 8-15, and if supported, the remainder of the 88-color or
2269	        // 256-color table.
2270	        // If a "?" is given rather than a name or RGB specification, xterm replies with a control sequence of the
2271	        // same form which can be used to set the corresponding color. Because more than one pair of color number
2272	        // and specification can be given in one control sequence, xterm can make more than one reply.
2273	        int colorIndex = -1;
2274	        int parsingPairStart = -1;
2275	        for (int i = 0; ; i++) {
2276	            boolean endOfInput = i == text.length();
2277	            char b = endOfInput ? ';' : text.charAt(i);
2278	            if (b == ';') {
2279	                if (parsingPairStart < 0) {
2280	                    parsingPairStart = i + 1;
2281	                } else {
2282	                    if (colorIndex < 0 || colorIndex > 255) {
2283	                        unknownSequence(b);
2284	                        return false;
2285	                    } else {
2286	                        mColors.tryParseColor(colorIndex, text.substring(parsingPairStart, i));
2287	                        mSession.onColorsChanged();
2288	                        colorIndex = -1;
2289	                        parsingPairStart = -1;
2290	                    }
2291	                }
2292	            } else if (parsingPairStart >= 0) {
2293	                // We have passed a color index and are now going through color spec.
2294	            } else if (parsingPairStart < 0 && (b >= '0' && b <= '9')) {
2295	                colorIndex = ((colorIndex < 0) ? 0 : colorIndex * 10) + (b - '0');
2296	            } else {
2297	                unknownSequence(b);
2298	                return false;
2299	            }
2300	            if (endOfInput) break;
2301	        }
2302	        return true;
2303	    }
