2305	    /** OSC 10/11/12 — set or report foreground/background/cursor color. */
2306	    private void oscSetOrReportSpecialColors(int value, String text, String bellOrStringTerminator) {
2307	        int specialIndex = TextStyle.COLOR_INDEX_FOREGROUND + (value - 10);
2308	        int lastSemiIndex = 0;
2309	        for (int charIndex = 0; ; charIndex++) {
2310	            boolean endOfInput = charIndex == text.length();
2311	            if (endOfInput || text.charAt(charIndex) == ';') {
2312	                try {
2313	                    String colorSpec = text.substring(lastSemiIndex, charIndex);
2314	                    if ("?".equals(colorSpec)) {
2315	                        // Report current color in the same format xterm and gnome-terminal does.
2316	                        int rgb = mColors.mCurrentColors[specialIndex];
2317	                        int r = (65535 * ((rgb & 0x00FF0000) >> 16)) / 255;
2318	                        int g = (65535 * ((rgb & 0x0000FF00) >> 8)) / 255;
2319	                        int b = (65535 * ((rgb & 0x000000FF))) / 255;
2320	                        mSession.write("\033]" + value + ";rgb:" + String.format(Locale.US, "%04x", r) + "/" + String.format(Locale.US, "%04x", g) + "/"
2321	                            + String.format(Locale.US, "%04x", b) + bellOrStringTerminator);
2322	                    } else {
2323	                        mColors.tryParseColor(specialIndex, colorSpec);
2324	                        mSession.onColorsChanged();
2325	                    }
2326	                    specialIndex++;
2327	                    if (endOfInput || (specialIndex > TextStyle.COLOR_INDEX_CURSOR) || ++charIndex >= text.length())
2328	                        break;
2329	                    lastSemiIndex = charIndex;
2330	                } catch (NumberFormatException e) {
2331	                    // Ignore.
2332	                }
2333	            }
2334	        }
2335	    }
