2337	    /** OSC 104 — reset one or all indexed colors. */
2338	    private void oscResetColors(String text) {
2339	        // "104;$c" → Reset Color Number $c. It is reset to the color specified by the corresponding X
2340	        // resource. Any number of c parameters may be given. These parameters correspond to the ANSI colors 0-7,
2341	        // their bright versions 8-15, and if supported, the remainder of the 88-color or 256-color table. If no
2342	        // parameters are given, the entire table will be reset.
2343	        if (text.isEmpty()) {
2344	            mColors.reset();
2345	            mSession.onColorsChanged();
2346	        } else {
2347	            int lastIndex = 0;
2348	            for (int charIndex = 0; ; charIndex++) {
2349	                boolean endOfInput = charIndex == text.length();
2350	                if (endOfInput || text.charAt(charIndex) == ';') {
2351	                    try {
2352	                        int colorToReset = Integer.parseInt(text.substring(lastIndex, charIndex));
2353	                        mColors.reset(colorToReset);
2354	                        mSession.onColorsChanged();
2355	                        if (endOfInput) break;
2356	                        charIndex++;
2357	                        lastIndex = charIndex;
2358	                    } catch (NumberFormatException e) {
2359	                        // Ignore.
2360	                    }
2361	                }
2362	            }
2363	        }
2364	    }
