2427	    /**
2428	     * Process the next ASCII character of a parameter.
2429	     *
2430	     * <p>You must use the ; character to separate parameters and : to separate sub-parameters.
2431	     *
2432	     * <p>Parameter characters modify the action or interpretation of the sequence. Originally
2433	     * you can use up to 16 parameters per sequence, but following at least xterm and alacritty
2434	     * we use a common space for parameters and sub-parameters, allowing 32 in total.
2435	     *
2436	     * <p>All parameters are unsigned, positive decimal integers, with the most significant
2437	     * digit sent first. Any parameter greater than 9999 (decimal) is set to 9999
2438	     * (decimal). If you do not specify a value, a 0 value is assumed. A 0 value
2439	     * or omitted parameter indicates a default value for the sequence. For most
2440	     * sequences, the default value is 1.
2441	     *
2442	     * <p>References:
2443	     * <a href="https://vt100.net/docs/vt510-rm/chapter4.html#S4.3.3">VT510 Video Terminal Programmer Information: Control Sequences</a>
2444	     * <a href="https://github.com/alacritty/vte/issues/22">alacritty/vte: Implement colon separated CSI parameters</a>
2445	     * */
2446	    private void parseArg(int b) {
2447	        if (b >= '0' && b <= '9') {
2448	            if (mArgIndex < mArgs.length) {
2449	                mArgs[mArgIndex] = Math.min(Math.max(0, mArgs[mArgIndex]) * 10 + (b - '0'), 9999);
2450	            }
2451	            continueSequence(mEscapeState);
2452	        } else if (b == ';' || b == ':') {
2453	            if (mArgIndex + 1 < mArgs.length) {
2454	                mArgIndex++;
2455	                if (b == ':') {
2456	                    mArgsSubParamsBitSet |= 1 << mArgIndex;
2457	                }
2458	            } else {
2459	                logError("Too many parameters when in state: " + mEscapeState);
2460	            }
2461	            continueSequence(mEscapeState);
2462	        } else {
2463	            unknownSequence(b);
2464	        }
2465	    }
