2546	    /**
2547	     * Send a Unicode code point to the screen.
2548	     *
2549	     * @param codePoint The code point of the character to display
2550	     */
2551	    private void emitCodePoint(int codePoint) {
2552	        mLastEmittedCodePoint = codePoint;
2553	        if (mUseLineDrawingUsesG0 ? mUseLineDrawingG0 : mUseLineDrawingG1) {
2554	            codePoint = translateLineDrawingCodePoint(codePoint);
2555	        }
2556	
2557	        final boolean autoWrap = isDecsetInternalBitSet(DECSET_BIT_AUTOWRAP);
2558	        final int displayWidth = WcWidth.width(codePoint);
2559	        final boolean cursorInLastColumn = mCursorCol == mRightMargin - 1;
2560	
2561	        if (autoWrap) {
2562	            if (cursorInLastColumn && ((mAboutToAutoWrap && displayWidth == 1) || displayWidth == 2)) {
2563	                mScreen.setLineWrap(mCursorRow);
2564	                mCursorCol = mLeftMargin;
2565	                if (mCursorRow + 1 < mBottomMargin) {
2566	                    mCursorRow++;
2567	                } else {
2568	                    scrollDownOneLine();
2569	                }
2570	            }
2571	        } else if (cursorInLastColumn && displayWidth == 2) {
2572	            // The behaviour when a wide character is output with cursor in the last column when
2573	            // autowrap is disabled is not obvious - it's ignored here.
2574	            return;
2575	        }
2576	
2577	        if (mInsertMode && displayWidth > 0) {
2578	            // Move character to right one space.
2579	            int destCol = mCursorCol + displayWidth;
2580	            if (destCol < mRightMargin)
2581	                mScreen.blockCopy(mCursorCol, mCursorRow, mRightMargin - destCol, 1, destCol, mCursorRow);
2582	        }
2583	
2584	        int offsetDueToCombiningChar = ((displayWidth <= 0 && mCursorCol > 0 && !mAboutToAutoWrap) ? 1 : 0);
2585	        int column = mCursorCol - offsetDueToCombiningChar;
2586	
2587	        // Fix TerminalRow.setChar() ArrayIndexOutOfBoundsException index=-1 exception reported
2588	        // The offsetDueToCombiningChar would never be 1 if mCursorCol was 0 to get column/index=-1,
2589	        // so was mCursorCol changed after the offsetDueToCombiningChar conditional by another thread?
2590	        // TODO: Check if there are thread synchronization issues with mCursorCol and mCursorRow, possibly causing others bugs too.
2591	        if (column < 0) column = 0;
2592	        mScreen.setChar(column, mCursorRow, codePoint, getStyle());
2593	
2594	        if (autoWrap && displayWidth > 0)
2595	            mAboutToAutoWrap = (mCursorCol == mRightMargin - displayWidth);
2596	
2597	        mCursorCol = Math.min(mCursorCol + displayWidth, mRightMargin - 1);
2598	    }
