2600	    /** Translates VT100 special-graphics (G0/G1 line-drawing) code points to Unicode. */
2601	    private static int translateLineDrawingCodePoint(int codePoint) {
2602	        // http://www.vt100.net/docs/vt102-ug/table5-15.html.
2603	        switch (codePoint) {
2604	            case '_': return ' ';    // Blank.
2605	            case '`': return '◆';   // Diamond.
2606	            case '0': return '█';   // Solid block.
2607	            case 'a': return '▒';   // Checker board.
2608	            case 'b': return '␉';   // Horizontal tab.
2609	            case 'c': return '␌';   // Form feed.
2610	            case 'd': return '\r';  // Carriage return.
2611	            case 'e': return '␊';   // Linefeed.
2612	            case 'f': return '°';   // Degree.
2613	            case 'g': return '±';   // Plus-minus.
2614	            case 'h': return '\n';  // Newline.
2615	            case 'i': return '␋';   // Vertical tab.
2616	            case 'j': return '┘';   // Lower right corner.
2617	            case 'k': return '┐';   // Upper right corner.
2618	            case 'l': return '┌';   // Upper left corner.
2619	            case 'm': return '└';   // Left left corner.
2620	            case 'n': return '┼';   // Crossing lines.
2621	            case 'o': return '⎺';   // Horizontal line - scan 1.
2622	            case 'p': return '⎻';   // Horizontal line - scan 3.
2623	            case 'q': return '─';   // Horizontal line - scan 5.
2624	            case 'r': return '⎼';   // Horizontal line - scan 7.
2625	            case 's': return '⎽';   // Horizontal line - scan 9.
2626	            case 't': return '├';   // T facing rightwards.
2627	            case 'u': return '┤';   // T facing leftwards.
2628	            case 'v': return '┴';   // T facing upwards.
2629	            case 'w': return '┬';   // T facing downwards.
2630	            case 'x': return '│';   // Vertical line.
2631	            case 'y': return '≤';   // Less than or equal to.
2632	            case 'z': return '≥';   // Greater than or equal to.
2633	            case '{': return 'π';   // Pi.
2634	            case '|': return '≠';   // Not equal to.
2635	            case '}': return '£';   // UK pound.
2636	            case '~': return '·';   // Centered dot.
2637	            default:  return codePoint;
2638	        }
2639	    }
