60	    public String getSelectedText(int selX1, int selY1, int selX2, int selY2, boolean joinBackLines, boolean joinFullLines) {
61	        final StringBuilder builder = new StringBuilder();
62	        final int columns = mColumns;
63	
64	        if (selY1 < -getActiveTranscriptRows()) selY1 = -getActiveTranscriptRows();
65	        if (selY2 >= mScreenRows) selY2 = mScreenRows - 1;
66	
67	        for (int row = selY1; row <= selY2; row++) {
68	            int x1 = (row == selY1) ? selX1 : 0;
69	            int x2;
70	            if (row == selY2) {
71	                x2 = Math.min(selX2 + 1, columns);
72	            } else {
73	                x2 = columns;
74	            }
75	            TerminalRow lineObject = mLines[externalToInternalRow(row)];
76	            int x1Index = lineObject.findStartOfColumn(x1);
77	            int x2Index = (x2 < mColumns) ? lineObject.findStartOfColumn(x2) : lineObject.getSpaceUsed();
78	            if (x2Index == x1Index) {
79	                // Selected the start of a wide character.
80	                x2Index = lineObject.findStartOfColumn(x2 + 1);
81	            }
82	            char[] line = lineObject.mText;
83	            int lastPrintingCharIndex = -1;
84	            int i;
85	            boolean rowLineWrap = getLineWrap(row);
86	            if (rowLineWrap && x2 == columns) {
87	                // If the line was wrapped, we shouldn't lose trailing space:
88	                lastPrintingCharIndex = x2Index - 1;
89	            } else {
90	                for (i = x1Index; i < x2Index; ++i) {
91	                    char c = line[i];
92	                    if (c != ' ') lastPrintingCharIndex = i;
93	                }
94	            }
95	
96	            int len = lastPrintingCharIndex - x1Index + 1;
97	            if (lastPrintingCharIndex != -1 && len > 0)
98	                builder.append(line, x1Index, len);
99	
100	            boolean lineFillsWidth = lastPrintingCharIndex == x2Index - 1;
101	            if ((!joinBackLines || !rowLineWrap) && (!joinFullLines || !lineFillsWidth)
102	                && row < selY2 && row < mScreenRows - 1) builder.append('\n');
103	        }
104	        return builder.toString();
105	    }
