107	    public String getWordAtLocation(int x, int y) {
108	        // Set y1 and y2 to the lines where the wrapped line starts and ends.
109	        // I.e. if a line that is wrapped to 3 lines starts at line 4, and this
110	        // is called with y=5, then y1 would be set to 4 and y2 would be set to 6.
111	        int y1 = y;
112	        int y2 = y;
113	        while (y1 > 0 && !getSelectedText(0, y1 - 1, mColumns, y, true, true).contains("\n")) {
114	            y1--;
115	        }
116	        while (y2 < mScreenRows && !getSelectedText(0, y, mColumns, y2 + 1, true, true).contains("\n")) {
117	            y2++;
118	        }
119	
120	        // Get the text for the whole wrapped line
121	        String text = getSelectedText(0, y1, mColumns, y2, true, true);
122	        // The index of x in text
123	        int textOffset = (y - y1) * mColumns + x;
124	
125	        if (textOffset >= text.length()) {
126	          // The click was to the right of the last word on the line, so
127	          // there's no word to return
128	          return "";
129	        }
130	
131	        // Set x1 and x2 to the indices of the last space before x and the
132	        // first space after x in text respectively
133	        int x1 = text.lastIndexOf(' ', textOffset);
134	        int x2 = text.indexOf(' ', textOffset);
135	        if (x2 == -1) {
136	            x2 = text.length();
137	        }
138	
139	        if (x1 == x2) {
140	          // The click was on a space, so there's no word to return
141	          return "";
142	        }
143	        return text.substring(x1 + 1, x2);
144	    }
