154	    /**
155	     * Convert a row value from the public external coordinate system to our internal private coordinate system.
156	     *
157	     * <pre>
158	     * - External coordinate system: -mActiveTranscriptRows to mScreenRows-1, with the screen being 0..mScreenRows-1.
159	     * - Internal coordinate system: the mScreenRows lines starting at mScreenFirstRow comprise the screen, while the
160	     *   mActiveTranscriptRows lines ending at mScreenFirstRow-1 form the transcript (as a circular buffer).
161	     *
162	     * External ↔ Internal:
163	     *
164	     * [ ...                            ]     [ ...                                     ]
165	     * [ -mActiveTranscriptRows         ]     [ mScreenFirstRow - mActiveTranscriptRows ]
166	     * [ ...                            ]     [ ...                                     ]
167	     * [ 0 (visible screen starts here) ]  ↔  [ mScreenFirstRow                         ]
168	     * [ ...                            ]     [ ...                                     ]
169	     * [ mScreenRows-1                  ]     [ mScreenFirstRow + mScreenRows-1         ]
170	     * </pre>
171	     *
172	     * @param externalRow a row in the external coordinate system.
173	     * @return The row corresponding to the input argument in the private coordinate system.
174	     */
175	    public int externalToInternalRow(int externalRow) {
176	        if (externalRow < -mActiveTranscriptRows || externalRow > mScreenRows)
177	            throw new IllegalArgumentException("extRow=" + externalRow + ", mScreenRows=" + mScreenRows + ", mActiveTranscriptRows=" + mActiveTranscriptRows);
178	        final int internalRow = mScreenFirstRow + externalRow;
179	        return (internalRow < 0) ? (mTotalRows + internalRow) : (internalRow % mTotalRows);
180	    }
