194	    /**
195	     * Resize the screen which this transcript backs. Currently, this only works if the number of columns does not
196	     * change or the rows expand (that is, it only works when shrinking the number of rows).
197	     *
198	     * @param newColumns The number of columns the screen should have.
199	     * @param newRows    The number of rows the screen should have.
200	     * @param cursor     An int[2] containing the (column, row) cursor location.
201	     */
202	    public void resize(int newColumns, int newRows, int newTotalRows, int[] cursor, long currentStyle, boolean altScreen) {
203	        // newRows > mTotalRows should not normally happen since mTotalRows is TRANSCRIPT_ROWS (10000):
204	        if (newColumns == mColumns && newRows <= mTotalRows) {
205	            resizeRowsOnly(newRows, newTotalRows, cursor, currentStyle, altScreen);
206	        } else {
207	            resizeWithReflow(newColumns, newRows, newTotalRows, cursor, currentStyle);
208	        }
209	        // Handle cursor scrolling off screen:
210	        if (cursor[0] < 0 || cursor[1] < 0) cursor[0] = cursor[1] = 0;
211	    }
