213	    /** Fast resize where only the row count changed (columns unchanged). */
214	    private void resizeRowsOnly(int newRows, int newTotalRows, int[] cursor, long currentStyle, boolean altScreen) {
215	        // Fast resize where just the rows changed.
216	        int shiftDownOfTopRow = mScreenRows - newRows;
217	        if (shiftDownOfTopRow > 0 && shiftDownOfTopRow < mScreenRows) {
218	            // Shrinking. Check if we can skip blank rows at bottom below cursor.
219	            for (int i = mScreenRows - 1; i > 0; i--) {
220	                if (cursor[1] >= i) break;
221	                int r = externalToInternalRow(i);
222	                if (mLines[r] == null || mLines[r].isBlank()) {
223	                    if (--shiftDownOfTopRow == 0) break;
224	                }
225	            }
226	        } else if (shiftDownOfTopRow < 0) {
227	            // Negative shift down = expanding. Only move screen up if there is transcript to show:
228	            int actualShift = Math.max(shiftDownOfTopRow, -mActiveTranscriptRows);
229	            if (shiftDownOfTopRow != actualShift) {
230	                // The new lines revealed by the resizing are not all from the transcript. Blank the below ones.
231	                for (int i = 0; i < actualShift - shiftDownOfTopRow; i++)
232	                    allocateFullLineIfNecessary((mScreenFirstRow + mScreenRows + i) % mTotalRows).clear(currentStyle);
233	                shiftDownOfTopRow = actualShift;
234	            }
235	        }
236	        mScreenFirstRow += shiftDownOfTopRow;
237	        mScreenFirstRow = (mScreenFirstRow < 0) ? (mScreenFirstRow + mTotalRows) : (mScreenFirstRow % mTotalRows);
238	        mTotalRows = newTotalRows;
239	        mActiveTranscriptRows = altScreen ? 0 : Math.max(0, mActiveTranscriptRows + shiftDownOfTopRow);
240	        cursor[1] -= shiftDownOfTopRow;
241	        mScreenRows = newRows;
242	    }
