244	    /** Full reflow resize: column count changed (or newRows > mTotalRows). Rewraps all lines. */
245	    private void resizeWithReflow(int newColumns, int newRows, int newTotalRows, int[] cursor, long currentStyle) {
246	        // Copy away old state and update new:
247	        TerminalRow[] oldLines = mLines;
248	        mLines = new TerminalRow[newTotalRows];
249	        for (int i = 0; i < newTotalRows; i++)
250	            mLines[i] = new TerminalRow(newColumns, currentStyle);
251	
252	        final int oldActiveTranscriptRows = mActiveTranscriptRows;
253	        final int oldScreenFirstRow = mScreenFirstRow;
254	        final int oldScreenRows = mScreenRows;
255	        final int oldTotalRows = mTotalRows;
256	        mTotalRows = newTotalRows;
257	        mScreenRows = newRows;
258	        mActiveTranscriptRows = mScreenFirstRow = 0;
259	        mColumns = newColumns;
260	
261	        int oldCursorRow = cursor[1];
262	        int oldCursorColumn = cursor[0];
263	        ReflowState state = new ReflowState();
264	
265	        // Loop over every character in the initial state.
266	        // Blank lines should be skipped only if at end of transcript (just as is done in the "fast" resize), so we
267	        // keep track how many blank lines we have skipped if we later on find a non-blank line.
268	        int skippedBlankLines = 0;
269	        for (int externalOldRow = -oldActiveTranscriptRows; externalOldRow < oldScreenRows; externalOldRow++) {
270	            // Do what externalToInternalRow() does but for the old state:
271	            int internalOldRow = oldScreenFirstRow + externalOldRow;
272	            internalOldRow = (internalOldRow < 0) ? (oldTotalRows + internalOldRow) : (internalOldRow % oldTotalRows);
273	
274	            TerminalRow oldLine = oldLines[internalOldRow];
275	            boolean cursorAtThisRow = externalOldRow == oldCursorRow;
276	            // The cursor may only be on a non-null line, which we should not skip:
277	            if (oldLine == null || (state.cursorPlaced || !cursorAtThisRow) && oldLine.isBlank()) {
278	                skippedBlankLines++;
279	                continue;
280	            } else if (skippedBlankLines > 0) {
281	                // After skipping some blank lines we encounter a non-blank line. Insert the skipped blank lines.
282	                for (int i = 0; i < skippedBlankLines; i++)
283	                    advanceReflowRow(state, false, currentStyle);
284	                skippedBlankLines = 0;
285	            }
286	
287	            int lastNonSpaceIndex;
288	            if (cursorAtThisRow || oldLine.mLineWrap) {
289	                // Take the whole line, either because of cursor on it, or if line wrapping.
290	                lastNonSpaceIndex = oldLine.getSpaceUsed();
291	            } else {
292	                lastNonSpaceIndex = 0;
293	                for (int i = 0; i < oldLine.getSpaceUsed(); i++)
294	                    // NEWLY INTRODUCED BUG! Should not index oldLine.mStyle with char indices
295	                    if (oldLine.mText[i] != ' '/* || oldLine.mStyle[i] != currentStyle */)
296	                        lastNonSpaceIndex = i + 1;
297	            }
298	
299	            reflowOldRow(oldLine, lastNonSpaceIndex, cursorAtThisRow, externalOldRow, oldCursorRow, oldCursorColumn, state, currentStyle);
300	
301	            // Old row has been copied. Check if we need to insert newline if old line was not wrapping:
302	            if (externalOldRow != (oldScreenRows - 1) && !oldLine.mLineWrap)
303	                advanceReflowRow(state, true, currentStyle);
304	        }
305	
306	        cursor[0] = state.newCursorColumn;
307	        cursor[1] = state.newCursorRow;
308	    }
309	
310	    /** Mutable state threaded through the reflow helpers to avoid 5 separate locals in resizeWithReflow. */
311	    private static final class ReflowState {
312	        int outputRow;
313	        int outputColumn;
314	        int newCursorRow = -1;
315	        int newCursorColumn = -1;
316	        boolean cursorPlaced;
317	    }
318	
319	    /**
320	     * Advance to the next output row during reflow (scroll or increment), resetting the output column.
321	     * When {@code adjustPlacedCursor} is true and the cursor has already been placed on a prior char,
322	     * decrement newCursorRow to compensate for the scroll (faithful to the original inline blocks).
323	     * Blank-line flushing uses false because it did not apply this adjustment in the original code.
324	     */
325	    private void advanceReflowRow(ReflowState state, boolean adjustPlacedCursor, long currentStyle) {
326	        if (state.outputRow == mScreenRows - 1) {
327	            if (adjustPlacedCursor && state.cursorPlaced) state.newCursorRow--;
328	            scrollDownOneLine(0, mScreenRows, currentStyle);
329	        } else {
330	            state.outputRow++;
331	        }
332	        state.outputColumn = 0;
333	    }
334	
335	    /** Process one old source row's characters into the reflow output, updating {@code state} in place. */
336	    private void reflowOldRow(TerminalRow oldLine, int lastNonSpaceIndex, boolean justToCursor,
337	                               int externalOldRow, int oldCursorRow, int oldCursorColumn,
338	                               ReflowState state, long currentStyle) {
339	        int currentOldCol = 0;
340	        long styleAtCol = 0;
341	        for (int i = 0; i < lastNonSpaceIndex; i++) {
342	            // Note that looping over java character, not cells.
343	            char c = oldLine.mText[i];
344	            int codePoint = (Character.isHighSurrogate(c)) ? Character.toCodePoint(c, oldLine.mText[++i]) : c;
345	            int displayWidth = WcWidth.width(codePoint);
346	            // Use the last style if this is a zero-width character:
347	            if (displayWidth > 0) styleAtCol = oldLine.getStyle(currentOldCol);
348	
349	            // Line wrap as necessary:
350	            if (state.outputColumn + displayWidth > mColumns) {
351	                setLineWrap(state.outputRow);
352	                advanceReflowRow(state, true, currentStyle);
353	            }
354	
355	            int offsetDueToCombiningChar = ((displayWidth <= 0 && state.outputColumn > 0) ? 1 : 0);
356	            setChar(state.outputColumn - offsetDueToCombiningChar, state.outputRow, codePoint, styleAtCol);
357	
358	            if (displayWidth > 0) {
359	                if (oldCursorRow == externalOldRow && oldCursorColumn == currentOldCol) {
360	                    state.newCursorColumn = state.outputColumn;
361	                    state.newCursorRow = state.outputRow;
362	                    state.cursorPlaced = true;
363	                }
364	                currentOldCol += displayWidth;
365	                state.outputColumn += displayWidth;
366	                if (justToCursor && state.cursorPlaced) break;
367	            }
368	        }
369	    }
