371	    /**
372	     * Block copy lines and associated metadata from one location to another in the circular buffer, taking wraparound
373	     * into account.
374	     *
375	     * @param srcInternal The first line to be copied.
376	     * @param len         The number of lines to be copied.
377	     */
378	    private void blockCopyLinesDown(int srcInternal, int len) {
379	        if (len == 0) return;
380	        int totalRows = mTotalRows;
381	
382	        int start = len - 1;
383	        // Save away line to be overwritten:
384	        TerminalRow lineToBeOverWritten = mLines[(srcInternal + start + 1) % totalRows];
385	        // Do the copy from bottom to top.
386	        for (int i = start; i >= 0; --i)
387	            mLines[(srcInternal + i + 1) % totalRows] = mLines[(srcInternal + i) % totalRows];
388	        // Put back overwritten line, now above the block:
389	        mLines[(srcInternal) % totalRows] = lineToBeOverWritten;
390	    }
391	
392	    /**
393	     * Scroll the screen down one line. To scroll the whole screen of a 24 line screen, the arguments would be (0, 24).
394	     *
395	     * @param topMargin    First line that is scrolled.
396	     * @param bottomMargin One line after the last line that is scrolled.
397	     * @param style        the style for the newly exposed line.
398	     */
399	    public void scrollDownOneLine(int topMargin, int bottomMargin, long style) {
400	        if (topMargin > bottomMargin - 1 || topMargin < 0 || bottomMargin > mScreenRows)
401	            throw new IllegalArgumentException("topMargin=" + topMargin + ", bottomMargin=" + bottomMargin + ", mScreenRows=" + mScreenRows);
402	
403	        // Copy the fixed topMargin lines one line down so that they remain on screen in same position:
404	        blockCopyLinesDown(mScreenFirstRow, topMargin);
405	        // Copy the fixed mScreenRows-bottomMargin lines one line down so that they remain on screen in same
406	        // position:
407	        blockCopyLinesDown(externalToInternalRow(bottomMargin), mScreenRows - bottomMargin);
408	
409	        // Update the screen location in the ring buffer:
410	        mScreenFirstRow = (mScreenFirstRow + 1) % mTotalRows;
411	        // Note that the history has grown if not already full:
412	        if (mActiveTranscriptRows < mTotalRows - mScreenRows) mActiveTranscriptRows++;
413	
414	        // Blank the newly revealed line above the bottom margin:
415	        int blankRow = externalToInternalRow(bottomMargin - 1);
416	        if (mLines[blankRow] == null) {
417	            mLines[blankRow] = new TerminalRow(mColumns, style);
418	        } else {
419	            mLines[blankRow].clear(style);
420	        }
421	    }
422	
423	    /**
424	     * Block copy characters from one position in the screen to another. The two positions can overlap. All characters
425	     * of the source and destination must be within the bounds of the screen, or else an InvalidParameterException will
426	     * be thrown.
427	     *
428	     * @param sx source X coordinate
429	     * @param sy source Y coordinate
430	     * @param w  width
431	     * @param h  height
432	     * @param dx destination X coordinate
433	     * @param dy destination Y coordinate
434	     */
435	    public void blockCopy(int sx, int sy, int w, int h, int dx, int dy) {
436	        if (w == 0) return;
437	        if (sx < 0 || sx + w > mColumns || sy < 0 || sy + h > mScreenRows || dx < 0 || dx + w > mColumns || dy < 0 || dy + h > mScreenRows)
438	            throw new IllegalArgumentException();
439	        boolean copyingUp = sy > dy;
440	        for (int y = 0; y < h; y++) {
441	            int y2 = copyingUp ? y : (h - (y + 1));
442	            TerminalRow sourceRow = allocateFullLineIfNecessary(externalToInternalRow(sy + y2));
443	            allocateFullLineIfNecessary(externalToInternalRow(dy + y2)).copyInterval(sourceRow, sx, sx + w, dx);
444	        }
445	    }
446	
447	    /**
448	     * Block set characters. All characters must be within the bounds of the screen, or else and
449	     * InvalidParemeterException will be thrown. Typically this is called with a "val" argument of 32 to clear a block
450	     * of characters.
451	     */
452	    public void blockSet(int sx, int sy, int w, int h, int val, long style) {
453	        if (sx < 0 || sx + w > mColumns || sy < 0 || sy + h > mScreenRows) {
454	            throw new IllegalArgumentException(
455	                "Illegal arguments! blockSet(" + sx + ", " + sy + ", " + w + ", " + h + ", " + val + ", " + mColumns + ", " + mScreenRows + ")");
456	        }
457	        for (int y = 0; y < h; y++)
458	            for (int x = 0; x < w; x++)
459	                setChar(sx + x, sy + y, val, style);
460	    }
461	
462	    public TerminalRow allocateFullLineIfNecessary(int row) {
463	        return (mLines[row] == null) ? (mLines[row] = new TerminalRow(mColumns, 0)) : mLines[row];
464	    }
465	
466	    public void setChar(int column, int row, int codePoint, long style) {
467	        if (row  < 0 || row >= mScreenRows || column < 0 || column >= mColumns)
468	            throw new IllegalArgumentException("TerminalBuffer.setChar(): row=" + row + ", column=" + column + ", mScreenRows=" + mScreenRows + ", mColumns=" + mColumns);
469	        row = externalToInternalRow(row);
470	        allocateFullLineIfNecessary(row).setChar(column, codePoint, style);
471	    }
472	
473	    public long getStyleAt(int externalRow, int column) {
474	        return allocateFullLineIfNecessary(externalToInternalRow(externalRow)).getStyle(column);
475	    }
