477	    /** Support for http://vt100.net/docs/vt510-rm/DECCARA and http://vt100.net/docs/vt510-rm/DECCARA */
478	    public void setOrClearEffect(int bits, boolean setOrClear, boolean reverse, boolean rectangular, int leftMargin, int rightMargin, int top, int left,
479	                                 int bottom, int right) {
480	        for (int y = top; y < bottom; y++) {
481	            TerminalRow line = mLines[externalToInternalRow(y)];
482	            int startOfLine = (rectangular || y == top) ? left : leftMargin;
483	            int endOfLine = (rectangular || y + 1 == bottom) ? right : rightMargin;
484	            for (int x = startOfLine; x < endOfLine; x++) {
485	                long currentStyle = line.getStyle(x);
486	                int foreColor = TextStyle.decodeForeColor(currentStyle);
487	                int backColor = TextStyle.decodeBackColor(currentStyle);
488	                int effect = TextStyle.decodeEffect(currentStyle);
489	                if (reverse) {
490	                    effect ^= bits;
491	                } else if (setOrClear) {
492	                    effect |= bits;
493	                } else {
494	                    effect &= ~bits;
495	                }
496	                line.mStyle[x] = TextStyle.encode(foreColor, backColor, effect);
497	            }
498	        }
499	    }
500	
501	    public void clearTranscript() {
502	        if (mScreenFirstRow < mActiveTranscriptRows) {
503	            Arrays.fill(mLines, mTotalRows + mScreenFirstRow - mActiveTranscriptRows, mTotalRows, null);
504	            Arrays.fill(mLines, 0, mScreenFirstRow, null);
505	        } else {
506	            Arrays.fill(mLines, mScreenFirstRow - mActiveTranscriptRows, mScreenFirstRow, null);
507	        }
508	        mActiveTranscriptRows = 0;
509	    }
