1	package com.termux.terminal;
2	
3	import java.util.Arrays;
4	
5	/**
6	 * A row in a terminal, composed of a fixed number of cells.
7	 * <p>
8	 * The text in the row is stored in a char[] array, {@link #mText}, for quick access during rendering.
9	 */
10	public final class TerminalRow {
11	
12	    private static final float SPARE_CAPACITY_FACTOR = 1.5f;
13	
14	    /**
15	     * Max combining characters that can exist in a column, that are separate from the base character
16	     * itself. Any additional combining characters will be ignored and not added to the column.
17	     *
18	     * There does not seem to be limit in unicode standard for max number of combination characters
19	     * that can be combined but such characters are primarily under 10.
20	     *
21	     * "Section 3.6 Combination" of unicode standard contains combining characters info.
22	     * - https://www.unicode.org/versions/Unicode15.0.0/ch03.pdf
23	     * - https://en.wikipedia.org/wiki/Combining_character#Unicode_ranges
24	     * - https://stackoverflow.com/questions/71237212/what-is-the-maximum-number-of-unicode-combined-characters-that-may-be-needed-to
25	     *
26	     * UAX15-D3 Stream-Safe Text Format limits to max 30 combining characters.
27	     * > The value of 30 is chosen to be significantly beyond what is required for any linguistic or technical usage.
28	     * > While it would have been feasible to chose a smaller number, this value provides a very wide margin,
29	     * > yet is well within the buffer size limits of practical implementations.
30	     * - https://unicode.org/reports/tr15/#Stream_Safe_Text_Format
31	     * - https://stackoverflow.com/a/11983435/14686958
32	     *
33	     * We choose the value 15 because it should be enough for terminal based applications and keep
34	     * the memory usage low for a terminal row, won't affect performance or cause terminal to
35	     * lag or hang, and will keep malicious applications from causing harm. The value can be
36	     * increased if ever needed for legitimate applications.
37	     */
38	    private static final int MAX_COMBINING_CHARACTERS_PER_COLUMN = 15;
39	
40	    /** The number of columns in this terminal row. */
41	    private final int mColumns;
42	    /** The text filling this terminal row. */
43	    public char[] mText;
44	    /** The number of java chars used in {@link #mText}. */
45	    private short mSpaceUsed;
46	    /** If this row has been line wrapped due to text output at the end of line. */
47	    boolean mLineWrap;
48	    /** The style bits of each cell in the row. See {@link TextStyle}. */
49	    final long[] mStyle;
50	    /** If this row might contain chars with width != 1, used for deactivating fast path */
51	    boolean mHasNonOneWidthOrSurrogateChars;
52	
53	    /** Construct a blank row (containing only whitespace, ' ') with a specified style. */
54	    public TerminalRow(int columns, long style) {
55	        mColumns = columns;
56	        mText = new char[(int) (SPARE_CAPACITY_FACTOR * columns)];
57	        mStyle = new long[columns];
58	        clear(style);
59	    }
60	
61	    /** NOTE: The sourceX2 is exclusive. */
62	    public void copyInterval(TerminalRow line, int sourceX1, int sourceX2, int destinationX) {
63	        mHasNonOneWidthOrSurrogateChars |= line.mHasNonOneWidthOrSurrogateChars;
64	        final int x1 = line.findStartOfColumn(sourceX1);
65	        final int x2 = line.findStartOfColumn(sourceX2);
66	        boolean startingFromSecondHalfOfWideChar = (sourceX1 > 0 && line.wideDisplayCharacterStartingAt(sourceX1 - 1));
67	        final char[] sourceChars = (this == line) ? Arrays.copyOf(line.mText, line.mText.length) : line.mText;
68	        int latestNonCombiningWidth = 0;
69	        for (int i = x1; i < x2; i++) {
70	            char sourceChar = sourceChars[i];
71	            int codePoint = Character.isHighSurrogate(sourceChar) ? Character.toCodePoint(sourceChar, sourceChars[++i]) : sourceChar;
72	            if (startingFromSecondHalfOfWideChar) {
73	                // Just treat copying second half of wide char as copying whitespace.
74	                codePoint = ' ';
75	                startingFromSecondHalfOfWideChar = false;
76	            }
77	            int w = WcWidth.width(codePoint);
78	            if (w > 0) {
79	                destinationX += latestNonCombiningWidth;
80	                sourceX1 += latestNonCombiningWidth;
81	                latestNonCombiningWidth = w;
82	            }
83	            setChar(destinationX, codePoint, line.getStyle(sourceX1));
84	        }
85	    }
86	
87	    public int getSpaceUsed() {
88	        return mSpaceUsed;
89	    }
90	
91	    /** Note that the column may end of second half of wide character. */
92	    public int findStartOfColumn(int column) {
93	        if (column == mColumns) return getSpaceUsed();
94	
95	        int currentColumn = 0;
96	        int currentCharIndex = 0;
97	        while (true) { // 0<2 1 < 2
98	            int newCharIndex = currentCharIndex;
99	            char c = mText[newCharIndex++]; // cci=1, cci=2
100	            boolean isHigh = Character.isHighSurrogate(c);
101	            int codePoint = isHigh ? Character.toCodePoint(c, mText[newCharIndex++]) : c;
102	            int wcwidth = WcWidth.width(codePoint); // 1, 2
103	            if (wcwidth > 0) {
104	                currentColumn += wcwidth;
105	                if (currentColumn == column) {
106	                    // Skip any following combining chars (width <= 0).
107	                    while (newCharIndex < mSpaceUsed && WcWidth.width(mText, newCharIndex) <= 0)
108	                        newCharIndex += Character.isHighSurrogate(mText[newCharIndex]) ? 2 : 1;
109	                    return newCharIndex;
110	                } else if (currentColumn > column) {
111	                    // Wide column going past end.
112	                    return currentCharIndex;
113	                }
114	            }
115	            currentCharIndex = newCharIndex;
116	        }
117	    }
118	
119	    private boolean wideDisplayCharacterStartingAt(int column) {
120	        for (int currentCharIndex = 0, currentColumn = 0; currentCharIndex < mSpaceUsed; ) {
121	            char c = mText[currentCharIndex++];
122	            int codePoint = Character.isHighSurrogate(c) ? Character.toCodePoint(c, mText[currentCharIndex++]) : c;
123	            int wcwidth = WcWidth.width(codePoint);
124	            if (wcwidth > 0) {
125	                if (currentColumn == column && wcwidth == 2) return true;
126	                currentColumn += wcwidth;
127	                if (currentColumn > column) return false;
128	            }
129	        }
130	        return false;
131	    }
132	
133	    public void clear(long style) {
134	        Arrays.fill(mText, ' ');
135	        Arrays.fill(mStyle, style);
136	        mSpaceUsed = (short) mColumns;
137	        mHasNonOneWidthOrSurrogateChars = false;
138	    }
