140	    // https://github.com/steven676/Android-Terminal-Emulator/commit/9a47042620bec87617f0b4f5d50568535668fe26
141	    public void setChar(int columnToSet, int codePoint, long style) {
142	        if (columnToSet  < 0 || columnToSet >= mStyle.length)
143	            throw new IllegalArgumentException("TerminalRow.setChar(): columnToSet=" + columnToSet + ", codePoint=" + codePoint + ", style=" + style);
144	
145	        mStyle[columnToSet] = style;
146	
147	        final int newCodePointDisplayWidth = WcWidth.width(codePoint);
148	
149	        // Fast path when we don't have any chars with width != 1
150	        if (!mHasNonOneWidthOrSurrogateChars) {
151	            if (codePoint >= Character.MIN_SUPPLEMENTARY_CODE_POINT || newCodePointDisplayWidth != 1) {
152	                mHasNonOneWidthOrSurrogateChars = true;
153	            } else {
154	                mText[columnToSet] = (char) codePoint;
155	                return;
156	            }
157	        }
158	
159	        final boolean newIsCombining = newCodePointDisplayWidth <= 0;
160	
161	        boolean wasExtraColForWideChar = (columnToSet > 0) && wideDisplayCharacterStartingAt(columnToSet - 1);
162	
163	        if (newIsCombining) {
164	            // When standing at second half of wide character and inserting combining:
165	            if (wasExtraColForWideChar) columnToSet--;
166	        } else {
167	            // Check if we are overwriting the second half of a wide character starting at the previous column:
168	            if (wasExtraColForWideChar) setChar(columnToSet - 1, ' ', style);
169	            // Check if we are overwriting the first half of a wide character starting at the next column:
170	            boolean overwritingWideCharInNextColumn = newCodePointDisplayWidth == 2 && wideDisplayCharacterStartingAt(columnToSet + 1);
171	            if (overwritingWideCharInNextColumn) setChar(columnToSet + 1, ' ', style);
172	        }
173	
174	        char[] text = mText;
175	        final int oldStartOfColumnIndex = findStartOfColumn(columnToSet);
176	        final int oldCodePointDisplayWidth = WcWidth.width(text, oldStartOfColumnIndex);
177	
178	        int oldCharactersUsedForColumn = countCharsUsedByColumn(columnToSet, oldCodePointDisplayWidth, oldStartOfColumnIndex);
179	
180	        // If MAX_COMBINING_CHARACTERS_PER_COLUMN already exist in column, then ignore adding additional combining characters.
181	        if (newIsCombining) {
182	            int combiningCharsCount = WcWidth.zeroWidthCharsCount(mText, oldStartOfColumnIndex, oldStartOfColumnIndex + oldCharactersUsedForColumn);
183	            if (combiningCharsCount >= MAX_COMBINING_CHARACTERS_PER_COLUMN)
184	                return;
185	        }
186	
187	        // Find how many chars this column will need
188	        int newCharactersUsedForColumn = Character.charCount(codePoint);
189	        if (newIsCombining) {
190	            // Combining characters are added to the contents of the column instead of overwriting them, so that they
191	            // modify the existing contents.
192	            // FIXME: Unassigned characters also get width=0.
193	            newCharactersUsedForColumn += oldCharactersUsedForColumn;
194	        }
195	
196	        int oldNextColumnIndex = oldStartOfColumnIndex + oldCharactersUsedForColumn;
197	        int newNextColumnIndex = oldStartOfColumnIndex + newCharactersUsedForColumn;
198	
199	        final int javaCharDifference = newCharactersUsedForColumn - oldCharactersUsedForColumn;
200	        if (javaCharDifference > 0) {
201	            // Shift the rest of the line right.
202	            text = shiftTail(text, oldNextColumnIndex, javaCharDifference);
203	        } else if (javaCharDifference < 0) {
204	            // Shift the rest of the line left.
205	            System.arraycopy(text, oldNextColumnIndex, text, newNextColumnIndex, mSpaceUsed - oldNextColumnIndex);
206	        }
207	        mSpaceUsed += javaCharDifference;
208	
209	        // Store char. A combining character is stored at the end of the existing contents so that it modifies them:
210	        //noinspection ResultOfMethodCallIgnored - since we already now how many java chars is used.
211	        Character.toChars(codePoint, text, oldStartOfColumnIndex + (newIsCombining ? oldCharactersUsedForColumn : 0));
212	
213	        adjustAfterWidthChange(oldCodePointDisplayWidth, newCodePointDisplayWidth, columnToSet, newNextColumnIndex);
214	    }
