216	    /** Returns how many java chars the given column occupies in mText, starting at {@code startIndex}. */
217	    private int countCharsUsedByColumn(int column, int displayWidth, int startIndex) {
218	        if (column + displayWidth < mColumns) {
219	            return findStartOfColumn(column + displayWidth) - startIndex;
220	        } else {
221	            // Last character.
222	            return mSpaceUsed - startIndex;
223	        }
224	    }
225	
226	    /**
227	     * Handle mText and mSpaceUsed adjustments when the display width of a column changes.
228	     * Called after the new codepoint has been stored but before returning from setChar.
229	     */
230	    private void adjustAfterWidthChange(int oldWidth, int newWidth, int columnToSet, int newNextColumnIndex) {
231	        if (oldWidth == 2 && newWidth == 1) {
232	            // Replace second half of wide char with a space. Which mean that we actually add a ' ' java character.
233	            shiftTail(mText, newNextColumnIndex, 1);
234	            mText[newNextColumnIndex] = ' ';
235	            ++mSpaceUsed;
236	        } else if (oldWidth == 1 && newWidth == 2) {
237	            if (columnToSet == mColumns - 1) {
238	                throw new IllegalArgumentException("Cannot put wide character in last column");
239	            } else if (columnToSet == mColumns - 2) {
240	                // Truncate the line to the second part of this wide char:
241	                mSpaceUsed = (short) newNextColumnIndex;
242	            } else {
243	                // Overwrite the contents of the next column, which mean we actually remove java characters. Due to the
244	                // check at the beginning of this method we know that we are not overwriting a wide char.
245	                int newNextNextColumnIndex = newNextColumnIndex + (Character.isHighSurrogate(mText[newNextColumnIndex]) ? 2 : 1);
